CASE_DETAIL_HTML = r"""
<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Карточка дела — Digital Legal Concierge</title>
<style>
:root{--bg:#f4f6fa;--surface:#fff;--ink:#172033;--muted:#667085;--line:#e4e7ec;--primary:#3157d5;--primary-soft:#eef2ff;--green:#14804a;--green-soft:#ecfdf3;--red:#b42318;--red-soft:#fef3f2;--amber:#a15c00;--amber-soft:#fff7e6;--shadow:0 12px 34px rgba(16,24,40,.07)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif}header{background:linear-gradient(135deg,#111827,#26334f);color:#fff;padding:20px 24px}header .inner{max-width:1180px;margin:auto;display:flex;justify-content:space-between;gap:18px;align-items:center}h1{font-size:23px;margin:0 0 4px}header p{margin:0;color:#d0d5dd;font-size:13px}.links,.row,.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.button,button{border:0;border-radius:10px;padding:9px 12px;background:var(--primary);color:#fff;font-weight:750;cursor:pointer;text-decoration:none;display:inline-block}.secondary{background:#475467}button.green{background:var(--green)}button:disabled,input:disabled,textarea:disabled{opacity:.55;cursor:wait}main{max-width:1180px;margin:auto;padding:22px}.hero{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:14px}.hero h2{margin:0 0 5px}.muted{color:var(--muted);font-size:13px}.badge{display:inline-flex;border-radius:999px;padding:6px 10px;background:var(--primary-soft);color:#2445b5;font-size:12px;font-weight:750}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.metric,.card,.financial-final{background:#fff;border:1px solid var(--line);border-radius:15px;padding:15px;box-shadow:var(--shadow)}.metric b{display:block;font-size:17px;margin-bottom:4px}.metric span{color:var(--muted);font-size:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;margin-top:14px}.card h3,.financial-final h3{margin:0 0 10px;font-size:17px}.action-box{background:var(--primary-soft);border:1px solid #c7d2fe;border-radius:12px;padding:12px;margin:12px 0}.data-grid,.finance-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.cell{background:#f8fafc;border-radius:10px;padding:9px}.cell span{display:block;color:var(--muted);font-size:11px;margin-bottom:3px}.item{border-top:1px solid var(--line);padding:10px 0}.item:first-of-type{border-top:0}.status{min-height:22px;margin:10px 0}.bad{color:var(--red)}.warn{color:var(--amber)}.ok{color:var(--green)}.loading,.error,.empty{padding:34px;text-align:center;border:1px dashed var(--line);border-radius:16px;color:var(--muted);background:#fff}.error{color:var(--red);background:var(--red-soft)}.financial-final{margin-top:14px}.financial-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:12px}.financial-head p{margin:4px 0 0}.health{display:inline-flex;border-radius:999px;padding:6px 10px;font-size:12px;font-weight:800;white-space:nowrap}.health.ok{background:var(--green-soft);color:var(--green)}.health.warning{background:var(--amber-soft);color:var(--amber)}.health.critical{background:var(--red-soft);color:var(--red)}.finance-metrics{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:12px}.finance-metric{background:#f8fafc;border:1px solid #eef1f5;border-radius:11px;padding:10px}.finance-metric span{display:block;font-size:11px;color:var(--muted);margin-bottom:4px}.finance-metric b{font-size:15px}.finance-steps{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin:12px 0}.finance-step{position:relative;border:1px solid var(--line);border-radius:12px;padding:11px;min-height:105px;background:#f8fafc}.finance-step:before{content:'';display:block;width:10px;height:10px;border-radius:50%;background:#98a2b3;margin-bottom:8px}.finance-step.complete{background:var(--green-soft);border-color:#abefc6}.finance-step.complete:before{background:var(--green)}.finance-step.current{background:var(--primary-soft);border-color:#c7d2fe}.finance-step.current:before{background:var(--primary)}.finance-step.blocked{background:var(--red-soft);border-color:#fecdca}.finance-step.blocked:before{background:var(--red)}.finance-step b{display:block;font-size:13px;margin-bottom:5px}.finance-step small{color:var(--muted);line-height:1.35}.diagnostics{display:grid;gap:7px;margin-top:10px}.diagnostic{border-radius:11px;padding:10px 11px;font-size:13px;line-height:1.4}.diagnostic.critical{background:var(--red-soft);border:1px solid #fecdca;color:var(--red)}.diagnostic.warning{background:var(--amber-soft);border:1px solid #fedf89;color:var(--amber)}.financial-next{margin-top:10px;border-radius:11px;padding:11px 12px;background:var(--primary-soft);border:1px solid #c7d2fe;font-size:13px}.financial-next strong{display:block;margin-bottom:4px}.readonly-note{font-size:12px;color:var(--muted);margin-top:8px}.offline-form{margin-top:9px;padding:10px;border:1px solid #abefc6;background:var(--green-soft);border-radius:11px}.offline-form label{display:block;font-size:12px;font-weight:700;margin-top:6px}.offline-form input,.offline-form textarea{width:100%;padding:9px;border:1px solid #d0d5dd;border-radius:9px;margin:5px 0;background:#fff}.offline-form textarea{min-height:78px;resize:vertical}.offline-form .muted{margin-bottom:5px}@media(max-width:900px){.finance-steps{grid-template-columns:repeat(3,minmax(0,1fr))}.finance-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:850px){.metrics,.grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){header .inner,.hero,.financial-head{align-items:flex-start;flex-direction:column}.metrics,.grid,.data-grid,.finance-metrics,.finance-steps{grid-template-columns:1fr}main{padding:14px}.finance-step{min-height:auto}}
</style>
</head>
<body>
<header><div class="inner"><div><h1>⚖ Карточка дела</h1><p>Статус, документы, клиент, сроки и действия в одном контексте</p></div><div class="links"><a class="button secondary" href="/admin/notification-delivery/ui">Telegram-доставка</a><a class="button secondary" href="/admin-ui">Админка</a><a class="button secondary" href="/operator">Все разделы</a></div></div></header>
<main><div id="status" class="status" role="status" aria-live="polite"></div><div id="content"><div class="loading">Загрузка карточки дела…</div></div></main>
<script>
const caseId=Number('__CASE_ID__');let token='';const content=document.getElementById('content'),statusBox=document.getElementById('status');
function esc(v){return String(v??'').replace(/[&<>\x22\x27]/g,c=>c==='&'?'&amp;':c==='<'?'&lt;':c==='>'?'&gt;':c.charCodeAt(0)===34?'&quot;':'&#39;')}
function feedback(text,state=''){statusBox.textContent=text;statusBox.className='status '+state}
function dt(v){return v?new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—'}
function money(v,currency='RUB'){if(v===null||v===undefined||v==='')return '—';const n=Number(v);if(!Number.isFinite(n))return esc(v)+' '+esc(currency);return new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)+' '+esc(currency)}
async function api(path,opts={}){const r=await fetch(path,{...opts,credentials:'same-origin',cache:'no-store',headers:{'x-admin-token':token,'Content-Type':'application/json',...(opts.headers||{})}});if(r.status===401||r.status===403){location.href='/login';throw new Error('Сессия истекла или недостаточно прав')}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detail||'Ошибка запроса');return d}
function docItem(x){return `<div class="item"><b>${esc(x.title)} · версия ${esc(x.version)}</b><br><span class="badge">${esc(x.status_label||'Статус уточняется')}</span><div class="muted">${esc(x.file_name||'Файл')} · ${esc(x.type||'')}</div>${x.lawyer_comment?`<div class="action-box"><b>Комментарий юриста</b>${esc(x.lawyer_comment)}</div>`:''}</div>`}
function paymentItem(x){const offline=x.offline_confirm_allowed?`<div class="actions" style="margin-top:8px"><button class="green" data-offline-payment="${x.id}" onclick="showOfflineForm(${x.id})">Подтвердить офлайн-поступление</button></div><div class="offline-form" id="offline_${x.id}" hidden><div class="muted">Используйте только после проверки фактического поступления денег. Статус дела изменится автоматически по штатной платёжной логике.</div><label for="offline_ref_${x.id}">Банковский / бухгалтерский референс</label><input id="offline_ref_${x.id}" maxlength="200" placeholder="Например: выписка 12345"><label for="offline_comment_${x.id}">Основание подтверждения</label><textarea id="offline_comment_${x.id}" maxlength="1000" placeholder="Что именно проверено и на основании какого документа"></textarea><div class="actions"><button class="green" data-offline-submit="${x.id}" data-expected-status="${esc(x.status)}" onclick="confirmOfflinePayment(${x.id},this)">Подтвердить поступление</button><button class="secondary" onclick="showOfflineForm(${x.id},false)">Отмена</button></div></div>`:'';return `<div class="item"><b>${esc(x.title)}</b><div>${money(x.amount,x.currency||'RUB')} · ${esc(x.status)}</div><div class="muted">${esc(x.payment_code||x.code||'')} ${x.provider?'· '+esc(x.provider):''} ${x.updated_at?'· обновлено '+esc(dt(x.updated_at)):''}</div>${offline}</div>`}
function healthLabel(v){return v==='critical'?'Найдена ошибка контура':v==='warning'?'Требует внимания':'Контур согласован'}
function financialFinal(f){if(!f?.applicable)return '';const steps=(f.steps||[]).map(s=>`<div class="finance-step ${esc(s.state||'pending')}"><b>${esc(s.title)}</b><small>${esc(s.detail||'')}</small></div>`).join('');const diagnostics=(f.diagnostics||[]).map(d=>`<div class="diagnostic ${esc(d.severity||'warning')}"><b>${d.severity==='critical'?'Ошибка':'Внимание'}.</b> ${esc(d.message||'')}</div>`).join('');const p=f.latest_payment||null;return `<section class="financial-final"><div class="financial-head"><div><h3>Финансовый финал M1</h3><p class="muted">Фактически взыскано → Success fee → платёж → подтверждение → закрытие</p></div><span class="health ${esc(f.health||'ok')}">${esc(healthLabel(f.health))}</span></div><div class="finance-metrics"><div class="finance-metric"><span>Фактически взыскано</span><b>${money(f.recovered_amount)}</b></div><div class="finance-metric"><span>Ставка success fee</span><b>${f.success_fee_percent!==null&&f.success_fee_percent!==undefined?esc(f.success_fee_percent)+'%':'—'}</b></div><div class="finance-metric"><span>Ожидаемый success fee</span><b>${money(f.expected_success_fee)}</b></div><div class="finance-metric"><span>Последний success fee</span><b>${p?money(p.amount,p.currency||'RUB')+' · '+esc(p.status):'нет записи'}</b></div></div><div class="finance-steps">${steps}</div>${diagnostics?`<div class="diagnostics">${diagnostics}</div>`:''}<div class="financial-next"><strong>Что делать сейчас</strong>${esc(f.recommended_action||'Проверьте актуальный этап дела.')}</div><div class="readonly-note">Статусы и суммы не исправляются здесь вручную. При отключённом онлайн-провайдере подтверждение фактического поступления ниже — отдельное штатное действие и требует референса и основания.</div></section>`}
function render(d){const x=d.case||{},client=d.client||null,docs=d.documents||[],payments=d.payments||[];const current=docs.filter(v=>v.status!=='ARCHIVED'),archived=docs.filter(v=>v.status==='ARCHIVED');content.innerHTML=`<div class="hero"><div><h2>${esc(x.number||'Дело')}</h2><div class="muted">${esc(x.route_label||'Юридическое обращение')} · обновлено ${esc(dt(x.updated_at))}</div></div><span class="badge">${esc(x.status_label||'Статус уточняется')}</span></div><div class="metrics"><article class="metric"><b>${esc(x.sla_label||'SLA не определён')}</b><span>срок: ${esc(dt(x.sla_due_at))}</span></article><article class="metric"><b>${esc(x.lawyer_name||'Не назначен')}</b><span>ответственный юрист</span></article><article class="metric"><b>${current.length}</b><span>актуальных документов</span></article><article class="metric"><b>${payments.length}</b><span>платёжных записей</span></article></div><div class="action-box"><b>Рекомендуемое действие</b>${esc(x.next_action||'Проверить актуальное состояние дела')}</div>${financialFinal(d.financial_final)}<div class="grid"><section class="card"><h3>Клиент и дело</h3><div class="data-grid"><div class="cell"><span>Клиент</span>${esc(client?.name||'Не найден')}</div><div class="cell"><span>Telegram</span>${esc(client?.username?('@'+client.username):'username не указан')}</div><div class="cell"><span>Маршрут</span>${esc(x.route_label||'—')}</div><div class="cell"><span>Ответственный</span>${esc(x.lawyer_name||'Не назначен')}</div></div><div class="actions" style="margin-top:12px"><a class="button" href="/message-center/ui?case_id=${caseId}">Открыть переписку по делу</a><a class="button secondary" href="/lawyer/workspace/ui">Кабинет юриста</a></div></section><section class="card"><h3>Документы</h3>${current.length?current.map(docItem).join(''):'<div class="empty">Актуальных документов нет.</div>'}${archived.length?`<details><summary>История версий (${archived.length})</summary>${archived.map(docItem).join('')}</details>`:''}<div class="actions" style="margin-top:12px"><a class="button" href="/document-access/review/ui">Центр проверки</a></div></section><section class="card"><h3>Платежи</h3><p class="muted">Финансовые действия показываются только когда они разрешены сервером для текущего платежа и режима оплаты.</p>${payments.length?payments.map(paymentItem).join(''):'<div class="empty">Платёжных записей нет.</div>'}</section><section class="card"><h3>Операционные действия</h3><p class="muted">Используйте профильные центры: они повторно проверяют права, snapshot и допустимость перехода.</p><div class="actions"><a class="button" href="/admin/notification-delivery/ui">Вернуться к доставке</a><a class="button secondary" href="/admin-ui">Все дела</a><a class="button secondary" href="/admin/sla/ui">SLA</a></div></section></div>`}
function showOfflineForm(paymentId,open=true){const form=document.getElementById('offline_'+paymentId);if(!form)return;form.hidden=open===false?true:!form.hidden;if(open===false)form.hidden=true}
async function confirmOfflinePayment(paymentId,button){const reference=(document.getElementById('offline_ref_'+paymentId)?.value||'').trim(),comment=(document.getElementById('offline_comment_'+paymentId)?.value||'').trim(),expected=button.dataset.expectedStatus||'';if(reference.length<3){feedback('Укажите банковский или бухгалтерский референс — минимум 3 символа.','bad');return}if(comment.length<5){feedback('Укажите основание подтверждения поступления — минимум 5 символов.','bad');return}if(!confirm('Подтвердить фактическое поступление денег? После этого платёж и этап дела изменятся автоматически.'))return;button.disabled=true;button.setAttribute('aria-busy','true');const old=button.textContent;button.textContent='Подтверждение…';try{const result=await api('/admin/payments/'+paymentId+'/confirm-offline',{method:'POST',body:JSON.stringify({expected_status:expected,reference,comment})});await load(false);feedback(`Поступление подтверждено. Платёж #${result.payment_id}: ${result.status}; дело: ${result.case_status}.`,'ok')}catch(e){feedback('Поступление не подтверждено: '+(e.message||e),'bad')}finally{const current=document.querySelector(`[data-offline-submit="${paymentId}"]`);if(current){current.disabled=false;current.removeAttribute('aria-busy');current.textContent=old}}}
function showError(e){content.innerHTML=`<div class="error"><b>Не удалось открыть дело #${esc(caseId)}</b><p>${esc(e.message||e)}</p><button onclick="load()">Повторить</button> <a class="button secondary" href="/admin/notification-delivery/ui">К доставке</a></div>`;feedback(e.message||String(e),'bad')}
async function load(showLoaded=true){content.innerHTML='<div class="loading">Загрузка карточки дела…</div>';if(showLoaded)feedback('');try{const workspace=await api('/admin/case-workspace/'+caseId);render(workspace);if(showLoaded)feedback('Карточка загружена','ok')}catch(e){showError(e)}}
async function boot(){try{const r=await fetch('/auth/session',{credentials:'same-origin',cache:'no-store'});if(!r.ok){location.href='/login';return}const s=await r.json();if(!(s.roles||[s.role]).includes('admin'))throw new Error('Требуется роль администратора');token=s.api_token||'';await load()}catch(e){showError(e)}}
boot();
</script>
</body>
</html>
"""
